import os, base64, zlib
R = "LockCOC" if os.path.isdir("LockCOC") else "."
p = os.path.join(R, "static/js/brandframe.js")
if not os.path.exists(p): raise SystemExit("[loi] can cai patch48 truoc")
B = ''
open(p, "w", encoding="utf-8").write(zlib.decompress(base64.b64decode(B)).decode("utf-8"))
print("[ok] patch49 xong: khung thuong hieu chi con logo, khong co chu")
